insert into public.missions (id, category, teaser, title, body, locale, is_active)
values
  ('a1f2e3d4-c5b6-4789-a012-345678010001'::uuid, 'social'::public.mission_category, 'There''s someone you only react to. Try words instead.', 'Mission: say something real', 'Open a chat with someone you usually only send emojis or likes to. Write one honest sentence about your day or theirs. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010003'::uuid, 'social'::public.mission_category, 'Someone in your contacts deserves a voice note.', 'Mission: send your voice', 'Record a short voice message for one person you trust. Keep it simple: a memory, a thank you, or a quick hello. You do not need to continue the conversation.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010004'::uuid, 'social'::public.mission_category, 'A familiar face is waiting for recognition.', 'Mission: acknowledge someone', 'Make eye contact with someone you see often but rarely speak to — a neighbor, cashier, receptionist, or barista. Say hello like you mean it. Stop there if you want.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010005'::uuid, 'social'::public.mission_category, 'Ask a question with no practical purpose.', 'Mission: ask something human', 'During your next conversation, ask someone what they''ve been enjoying lately. Don''t turn it into advice or recommendations. Just stay curious for two minutes.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010006'::uuid, 'social'::public.mission_category, 'A compliment is sitting unsent.', 'Mission: say the nice thing', 'Think of one specific thing you appreciate about someone. Tell them directly in one sentence. No extra explanation needed.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010008'::uuid, 'social'::public.mission_category, 'Call someone without needing anything.', 'Mission: unexpected call', 'Phone one person you usually only text. Keep the call under five minutes if you want. The point is hearing a voice.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010009'::uuid, 'social'::public.mission_category, 'There''s a tiny favor you can offer.', 'Mission: make life lighter', 'Ask someone nearby if they need help carrying, moving, or reaching something small. Accept yes or no without insisting. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010010'::uuid, 'social'::public.mission_category, 'One message can reopen a quiet friendship.', 'Mission: reopen the thread', 'Send a short message to someone you haven''t spoken to in months. Mention a memory or ask how they''ve been lately. You don''t need to explain the silence.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010012'::uuid, 'social'::public.mission_category, 'Your future self might remember this stranger.', 'Mission: ask for a recommendation', 'Ask someone nearby for a recommendation — a bakery item, a park, a movie, anything local and simple. Thank them and move on. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010013'::uuid, 'social'::public.mission_category, 'Sit closer to people today.', 'Mission: choose proximity', 'In a public place, sit near other people instead of automatically choosing the isolated corner. Stay present for a few minutes. No conversation required.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010014'::uuid, 'social'::public.mission_category, 'There''s a thank-you you forgot to send.', 'Mission: close the loop', 'Message someone who helped you recently, even in a small way. Be specific about what you appreciated. Stop after sending it.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010015'::uuid, 'social'::public.mission_category, 'Share a memory instead of an update.', 'Mission: bring something back', 'Text someone a memory you still laugh about or think about sometimes. Don''t add a photo or link. Just the moment itself.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010016'::uuid, 'social'::public.mission_category, 'You can make someone feel noticed in 10 seconds.', 'Mission: use their name', 'During your next interaction, say the person''s name out loud once if you know it. Keep the rest natural. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010017'::uuid, 'social'::public.mission_category, 'A tiny invitation counts.', 'Mission: ask someone along', 'Invite someone to join you for a very small thing today — a coffee run, short walk, or quick errand. Keep it low pressure. One ask is enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010018'::uuid, 'social'::public.mission_category, 'Be the first person to wave.', 'Mission: start the hello', 'When you pass someone familiar today, greet them before they greet you. Keep walking if you want afterward. Stop there.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010019'::uuid, 'social'::public.mission_category, 'One honest answer could change the tone.', 'Mission: answer properly', 'The next time someone asks how you are, answer with one real sentence instead of autopilot. Nothing dramatic required. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010021'::uuid, 'social'::public.mission_category, 'Someone around you has a story you''ll never hear.', 'Mission: small curiosity', 'Ask a simple follow-up question during a casual interaction today. Stay with the answer instead of turning back to yourself immediately. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010022'::uuid, 'social'::public.mission_category, 'An old friend might answer faster than you think.', 'Mission: random check-in', 'Choose one person you haven''t thought about in a while. Send a short message asking what life has been like lately. Stop after pressing send.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010024'::uuid, 'social'::public.mission_category, 'You don''t need a reason to reach out.', 'Mission: send the first text', 'Start a conversation today without needing news, plans, or logistics. A simple "thought of you" is enough. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010025'::uuid, 'social'::public.mission_category, 'Notice who always initiates with you.', 'Mission: reverse the pattern', 'Think of someone who usually reaches out first. Contact them before they contact you this time. Keep it short and easy.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010032'::uuid, 'social'::public.mission_category, 'You already know more neighbors than you think.', 'Mission: hallway hello', 'If you cross paths with a neighbor today, pause for one extra sentence instead of a quick nod. Keep it casual and brief. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010033'::uuid, 'social'::public.mission_category, 'One person deserves your full attention for 2 minutes.', 'Mission: listen without fixing', 'During one conversation today, resist giving advice or turning the topic back to yourself. Just listen until the other person finishes. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010035'::uuid, 'social'::public.mission_category, 'A real laugh sounds better out loud.', 'Mission: share something funny', 'Tell someone about a genuinely funny thing that happened recently instead of sending a clip or meme. Keep it imperfect. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010036'::uuid, 'social'::public.mission_category, 'Notice who makes your days easier.', 'Mission: appreciate the regulars', 'Thank someone whose work quietly supports your routine — cleaner, driver, receptionist, cashier, delivery worker. Keep it direct and simple. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010037'::uuid, 'social'::public.mission_category, 'A question can change a whole mood.', 'Mission: ask about today', 'Ask someone what the best part of their day has been so far. Listen to the first answer without rushing onward. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010039'::uuid, 'social'::public.mission_category, 'There''s probably a local regular you recognize.', 'Mission: become familiar', 'Return to a place you visit sometimes and stay long enough for one brief interaction with the people there. Recognition counts. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010040'::uuid, 'social'::public.mission_category, 'Try one tiny act of trust.', 'Mission: ask for help', 'Ask someone for a small favor today — directions, an opinion, help opening something, a recommendation. Let them help if they want to. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010042'::uuid, 'social'::public.mission_category, 'Someone in your life needs encouragement.', 'Mission: back someone up', 'Send a message reminding someone that they''re doing better than they think at something specific. Keep it grounded and short. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010043'::uuid, 'social'::public.mission_category, 'You can change the energy of a room quietly.', 'Mission: arrive open', 'When entering a shared space today, look up instead of immediately disappearing into your own world. A smile or nod is enough. Stop there.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010044'::uuid, 'social'::public.mission_category, 'Reconnect through a shared memory.', 'Mission: remember together', 'Message someone about a place, song, meal, or moment you both experienced. Let the memory sit without forcing a long conversation. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010046'::uuid, 'social'::public.mission_category, 'Someone would probably answer if you invited them.', 'Mission: make a simple plan', 'Invite one person to do something low-effort this week — coffee, lunch, a walk, browsing a shop. Keep the invitation casual. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010047'::uuid, 'social'::public.mission_category, 'Try noticing the quiet people.', 'Mission: include someone', 'During a group moment today, direct one question toward the quieter person in the room. Give them space to answer. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010049'::uuid, 'social'::public.mission_category, 'Your attention is useful to someone.', 'Mission: notice effort', 'Tell someone you noticed a specific effort they made recently — cooking, organizing, showing up, helping, trying. Keep it sincere and brief. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020001'::uuid, 'nature'::public.mission_category, 'The sky is doing something right now.', 'Mission: look up', 'Step outside or find a window. Spend one minute looking only at the sky and notice three different shades or movements. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020002'::uuid, 'nature'::public.mission_category, 'There''s a tree you pass without seeing.', 'Mission: meet a tree', 'Find the nearest tree, even a tiny city one. Stand near it for 30 seconds and notice the shape of its bark or branches. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020003'::uuid, 'nature'::public.mission_category, 'Open a door. Hear the city differently.', 'Mission: sound check', 'Pause outside for two minutes without music or conversation. Count five separate sounds you can hear at the same time. You can head back in after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020004'::uuid, 'nature'::public.mission_category, 'The weather has a texture today.', 'Mission: feel the air', 'Step outside for one minute — even just the sidewalk outside your building. Pay attention to the air on your face and hands. Warm, damp, sharp, heavy — describe it silently to yourself. Stop there.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020005'::uuid, 'nature'::public.mission_category, 'Find one living thing you usually ignore.', 'Mission: tiny life', 'Notice one small living thing nearby — moss, weeds, insects, pigeons, anything. Watch it closely for 60 seconds without taking a photo. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020006'::uuid, 'nature'::public.mission_category, 'Walk slower for exactly one block.', 'Mission: slower route', 'During your next walk, slow your pace for one block. Notice what changes when you stop rushing past the street around you. Stop after that block.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020007'::uuid, 'nature'::public.mission_category, 'There''s movement above you right now.', 'Mission: cloud watch', 'Look at the clouds for two minutes, even if there are only a few. Follow their direction and speed without doing anything else. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020008'::uuid, 'nature'::public.mission_category, 'Borrow five minutes from the evening light.', 'Mission: sunset pause', 'If the timing works today, step outside near sunset. Watch the light change on buildings, pavement, or faces for five quiet minutes. Head back in whenever you''re ready.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020009'::uuid, 'nature'::public.mission_category, 'The ground under you has details.', 'Mission: pavement study', 'Walk slowly for two minutes while looking down instead of ahead. Notice cracks, leaves, reflections, or patterns in the ground. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020011'::uuid, 'nature'::public.mission_category, 'Notice what survives in your neighborhood.', 'Mission: urban green', 'Find one patch of green nearby — a planter, balcony vine, park edge, anything. Spend a minute looking at how it fits into the street around it. Stop there.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020013'::uuid, 'nature'::public.mission_category, 'Find the quietest outdoor spot nearby.', 'Mission: quiet corner', 'Walk until you find a slightly calmer outdoor spot — a bench, side street, courtyard, or corner. Stay there for three minutes and let the street noise settle around you. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020014'::uuid, 'nature'::public.mission_category, 'Something outside is reflecting light.', 'Mission: reflections', 'Look for reflections outdoors — puddles, windows, metal, sunglasses, anything. Spend two minutes noticing how light changes surfaces. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020015'::uuid, 'nature'::public.mission_category, 'Night air feels different.', 'Mission: step into night', 'Go outside after dark for five minutes if you can. Notice the sounds, temperature, and pace of the street at night compared to daytime. Head back in after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020016'::uuid, 'nature'::public.mission_category, 'Watch wind without looking at the wind.', 'Mission: moving things', 'Find something the wind is affecting — leaves, clothes, flags, hair, water. Watch the movement for one minute. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020017'::uuid, 'nature'::public.mission_category, 'Find one natural color today.', 'Mission: color search', 'Choose one color before stepping outside. Spend five minutes spotting that color in plants, sky, stone, water, or light around you. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020018'::uuid, 'nature'::public.mission_category, 'There are birds somewhere nearby.', 'Mission: listen for birds', 'Open a window or go outside for two minutes. Listen carefully for bird sounds hidden under the rest of the city noise. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020019'::uuid, 'nature'::public.mission_category, 'Sunlight lands differently every hour.', 'Mission: follow the light', 'Notice one patch of sunlight indoors or outside. Watch how it shifts or changes shape for a minute before moving on. Stop there.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020020'::uuid, 'nature'::public.mission_category, 'Find water, even a tiny bit.', 'Mission: water nearby', 'Look for water around you — a fountain, puddle, river, rain gutter, coffee steam, anything. Spend one minute paying attention to how it moves. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020021'::uuid, 'nature'::public.mission_category, 'Take the slightly greener path.', 'Mission: detour through green', 'On your next short walk, choose the route with more trees or open sky, even if it''s only one extra minute. Notice how the space feels different. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020022'::uuid, 'nature'::public.mission_category, 'Stand still outside for longer than usual.', 'Mission: pause outdoors', 'Find a place outside to stand still for three minutes. Let people, bikes, clouds, and sounds move around you while you stay put. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020023'::uuid, 'nature'::public.mission_category, 'Morning air has its own personality.', 'Mission: early air', 'If you''re awake early enough, step outside for two minutes before the day fully starts. Notice what the street sounds like before it fills up. Head back in after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020024'::uuid, 'nature'::public.mission_category, 'Look for nature in the wrong places.', 'Mission: unexpected green', 'Find one natural thing growing or existing where it probably wasn''t planned to — cracks, walls, rooftops, fences. Give it a full minute of attention. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020025'::uuid, 'nature'::public.mission_category, 'The temperature changes block by block.', 'Mission: temperature map', 'During a short walk, notice where the air gets cooler, warmer, shaded, or windy. Pay attention for five minutes, then move on with your day.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020026'::uuid, 'nature'::public.mission_category, 'Touch something natural today.', 'Mission: texture check', 'Touch bark, stone, grass, leaves, or even rough concrete outside. Spend 30 seconds noticing texture instead of rushing past it. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020029'::uuid, 'nature'::public.mission_category, 'Notice shadows instead of objects.', 'Mission: shadow watch', 'Spend two minutes paying attention only to shadows outdoors. Watch how they stretch, overlap, or move as people and light shift around you. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020030'::uuid, 'nature'::public.mission_category, 'There''s weather happening even on ordinary days.', 'Mission: today''s atmosphere', 'Step outside for one minute. Notice whether today feels heavy, bright, soft, restless, or clear — in the air, the light, the pace around you. Stop there.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678901103'::uuid, 'nature'::public.mission_category, '30 seconds. No goal. Just look.', 'Mission: notice the outside', 'Go to a window or step outside for 30 seconds. Name one thing you never really noticed before — a sound, a shape, a color.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678901104'::uuid, 'nature'::public.mission_category, 'Touch something alive.', 'Mission: connect with the living world', 'Find a plant, a tree, grass, or a pet. Touch it gently. Take one slow breath while you do.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030001'::uuid, 'curiosity'::public.mission_category, 'There''s a story hiding in an ordinary object.', 'Mission: object detective', 'Choose one everyday object near you. Study it for two minutes and list three details you had never noticed before. Invent one question about how it came to be there. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030002'::uuid, 'curiosity'::public.mission_category, 'Ask a question you normally leave unasked.', 'Mission: one real question', 'The next time you speak with someone today, ask them about a hobby, skill, or routine they know well. Listen to the answer without changing the subject. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030003'::uuid, 'curiosity'::public.mission_category, 'A sound nearby deserves your attention.', 'Mission: follow a sound', 'Pause for one minute and notice a sound in your surroundings. Trace where it might be coming from and what could be creating it. When your curiosity feels satisfied, stop.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030004'::uuid, 'curiosity'::public.mission_category, 'One sign or label can open a rabbit hole.', 'Mission: read the fine print', 'Find a sign, label, plaque, or notice you usually ignore. Read every word. Notice one detail that changes how you see that place or object. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030005'::uuid, 'curiosity'::public.mission_category, 'Take a different route with your eyes.', 'Mission: look higher', 'Walk a short distance or look out a window. Spend two minutes noticing what is above eye level—roofs, branches, wires, clouds, or architecture. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030006'::uuid, 'curiosity'::public.mission_category, 'Something nearby has changed recently.', 'Mission: spot the difference', 'Look around a familiar room, street, yard, or path. Find one thing that wasn''t there before or has shifted since you last paid attention. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030008'::uuid, 'curiosity'::public.mission_category, 'Count something nobody usually counts.', 'Mission: unusual tally', 'Choose one thing around you—red doors, birds, parked bicycles, fence posts, or something else. Count them for two minutes. When the timer ends, you''re done.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030009'::uuid, 'curiosity'::public.mission_category, 'Your neighborhood has a tiny mystery.', 'Mission: trace a clue', 'Notice an object that seems out of place. Spend a few minutes imagining two possible explanations for how it got there. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030010'::uuid, 'curiosity'::public.mission_category, 'Look for evidence of a hidden process.', 'Mission: behind the scenes', 'Find something being maintained, repaired, grown, cleaned, built, or organized. Observe it closely for a minute. Notice signs of the work behind it. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030011'::uuid, 'curiosity'::public.mission_category, 'One shelf can teach you something.', 'Mission: inspect a shelf', 'Choose a shelf, cupboard, drawer, or storage space. Pick one item and wonder why it was kept. Follow that question for a few minutes, then stop.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030012'::uuid, 'curiosity'::public.mission_category, 'Notice what repeats.', 'Mission: find a pattern', 'Look around your environment and identify a repeating shape, sound, color, or behavior. Spend two minutes tracking where else it appears. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030013'::uuid, 'curiosity'::public.mission_category, 'A place you know has an overlooked corner.', 'Mission: explore the edge', 'Visit a familiar room, yard, hallway, or outdoor spot. Pay attention to the least-noticed corner for three minutes. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030014'::uuid, 'curiosity'::public.mission_category, 'Borrow someone else''s perspective.', 'Mission: ask for a favorite', 'Ask someone to tell you their favorite local place, object, view, or routine. Learn why they chose it. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030015'::uuid, 'curiosity'::public.mission_category, 'Something old still has a secret.', 'Mission: date an object', 'Find an older item in your home or surroundings. Look for clues about when it was made or first used. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030016'::uuid, 'curiosity'::public.mission_category, 'Change one angle. See what appears.', 'Mission: new viewpoint', 'Stand, sit, or crouch somewhere you usually pass through. Spend one minute observing from that different height. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030017'::uuid, 'curiosity'::public.mission_category, 'What happens here when you''re not looking?', 'Mission: imagine the timeline', 'Choose a place nearby. Picture what it looked like five years ago and what it might look like five years from now. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030018'::uuid, 'curiosity'::public.mission_category, 'Read a name and wonder about it.', 'Mission: notice names', 'Look for a street name, building name, product name, or family name. Spend a few minutes guessing the story behind it before moving on. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030021'::uuid, 'curiosity'::public.mission_category, 'Your hands know more than your eyes.', 'Mission: texture survey', 'Carefully touch three different surfaces around you. Compare their textures and notice which details are easiest to miss visually. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030022'::uuid, 'curiosity'::public.mission_category, 'A routine path has a missing detail.', 'Mission: reverse attention', 'Walk a familiar route and look for what you normally ignore rather than what usually catches your eye. Notice three things. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030023'::uuid, 'curiosity'::public.mission_category, 'Look for evidence, not answers.', 'Mission: tiny investigation', 'Choose a mark, track, crack, stain, or worn spot. Spend two minutes imagining what repeated action created it. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030024'::uuid, 'curiosity'::public.mission_category, 'The weather is doing more than you think.', 'Mission: weather clues', 'Step outside or look through a window. Find three signs of today''s weather besides temperature. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030025'::uuid, 'curiosity'::public.mission_category, 'Find the oldest thing you can see.', 'Mission: age hunt', 'Look around your surroundings and choose the object, structure, or tree that seems oldest. Notice the clues that led you there. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030026'::uuid, 'curiosity'::public.mission_category, 'One minute of listening can reveal a map.', 'Mission: sound map', 'Close your eyes for sixty seconds. Identify as many distinct sounds as you can and imagine where each one is coming from. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030028'::uuid, 'curiosity'::public.mission_category, 'Ask about a first time.', 'Mission: first memories', 'Talk with someone and ask about the first time they learned, tried, or experienced something important to them. Listen to the story. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030029'::uuid, 'curiosity'::public.mission_category, 'Choose a direction you rarely notice.', 'Mission: look behind you', 'Turn around and study the space behind where you usually sit, stand, or wait. Spend one minute noticing details you normally miss. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030030'::uuid, 'curiosity'::public.mission_category, 'There''s a question hiding in plain sight.', 'Mission: wonder aloud', 'Write down one question about something you encounter today. Don''t answer it yet. Let the question exist for a few minutes, then move on.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678901107'::uuid, 'adventure'::public.mission_category, 'Change the route. Change the day.', 'Mission: take a different path', 'On your next walk or commute, take one different turn — even a small one. Pay attention to what’s different.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678901108'::uuid, 'creativity'::public.mission_category, 'Make something small, just for you.', 'Mission: a 5-minute creation', 'For five minutes, make something with your hands — doodle, fold paper, hum a melody, rearrange a corner of your space. No posting required.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678901109'::uuid, 'calm'::public.mission_category, 'Silence is not empty.', 'Mission: give your brain quiet', 'Sit or stand still for two minutes without a podcast, video, or feed. Hear the room. Let your mind drift without grabbing new input.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678901110'::uuid, 'learning'::public.mission_category, 'One skill, tiny step.', 'Mission: micro-practice', 'Pick something you’ve wanted to learn. Do exactly one tiny practice — one chord, one sentence, one stretch, one line read aloud. Stop after that one step.', 'en', true)
